{% extends "templates/print/ph_basis.html" %}
{% set sf = frappe.get_doc("PH Servicefall", doc.servicefall) if doc.servicefall else None %}
{% set techniker = frappe.db.get_value("User", doc.techniker, "full_name") if doc.techniker else "" %}
{% block titel %}Servicebericht {{ doc.name }}{% endblock %}
{% block kopfrechts %}Servicebericht {{ doc.name }}<br>{{ ph_datum(doc.datum) }}{% if sf %}<br>Servicefall {{ sf.name }}{% endif %}{% endblock %}
{% block inhalt %}
<h1>Servicebericht</h1>
<table style="width:100%;margin-bottom:5mm"><tr>
<td style="width:50%;vertical-align:top"><div class="ph-feld"><b>Kunde</b> {{ doc.kunde_name or "" }}</div><div class="ph-feld"><b>Einsatzort</b> {{ doc.strasse or "" }}, {{ doc.plz or "" }} {{ doc.ort or "" }}</div>{% if sf %}<div class="ph-feld"><b>Produkt</b> {{ sf.produkt_name or sf.produkt or "–" }}{% if sf.marke %} ({{ sf.marke }}){% endif %}</div><div class="ph-feld"><b>Fehler</b> {{ sf.fehlercode or "" }} {{ sf.fehlercode_bezeichnung or "" }}</div>{% endif %}</td>
<td style="width:50%;vertical-align:top"><div class="ph-feld"><b>Techniker</b> {{ techniker }}</div><div class="ph-feld"><b>Art</b> {{ _(doc.art) }}</div><div class="ph-feld"><b>Zeit vor Ort</b> {{ doc.ankunft.strftime("%H:%M") if doc.ankunft else "–" }} – {{ doc.abfahrt.strftime("%H:%M") if doc.abfahrt else "–" }} ({{ doc.zeit_arbeit_min or 0 }} min Arbeit{% if doc.zeit_pause_min %}, {{ doc.zeit_pause_min }} min Pause{% endif %})</div><div class="ph-feld"><b>Anfahrt</b> {{ doc.zeit_anfahrt_min or 0 }} min{% if doc.anfahrt_km %} · {{ doc.anfahrt_km }} km{% endif %}</div>{% if doc.zeit_abrechenbar_min %}<div class="ph-feld"><b>Abrechenbar</b> {{ doc.zeit_abrechenbar_min }} min</div>{% endif %}<div class="ph-feld"><b>Ergebnis</b> {{ _(doc.ergebnis) if doc.ergebnis else "–" }}</div></td></tr></table>
<h2>Durchgeführte Arbeiten</h2>
<div>{{ doc.bericht or "–" }}</div>
{% if doc.ersatzteile %}<h2>Ersatzteile</h2><table class="ph-tabelle"><thead><tr><th>Bezeichnung</th><th class="zahl">Menge</th></tr></thead><tbody>{% for z in doc.ersatzteile %}<tr><td>{{ z.bezeichnung or z.ersatzteil }}</td><td class="zahl">{{ z.menge }}</td></tr>{% endfor %}</tbody></table>{% endif %}
{% set bilder = doc.fotos | selectattr("bild") | list %}{% if bilder %}<h2>Fotos</h2><table style="width:100%"><tr>{% for z in bilder[:6] %}<td style="width:33%;padding:2mm;text-align:center;vertical-align:top"><img src="{{ frappe.utils.get_url(z.bild) }}" style="max-width:100%;max-height:45mm"><div style="font-size:8pt;color:#6b7280">{{ _(z.phase) }} {{ z.hinweis or "" }}</div></td>{% if loop.index % 3 == 0 and not loop.last %}</tr><tr>{% endif %}{% endfor %}</tr></table>{% endif %}
{% if doc.folgeeinsatz_noetig %}<p class="ph-hinweis">Ein weiterer Einsatz ist erforderlich{% if doc.ergebnis == "Ersatzteil noetig" %} (Ersatzteil wird beim Hersteller bestellt){% endif %}. Wir melden uns mit einem Terminvorschlag.</p>{% endif %}
<h2>Bestätigung</h2>
<table style="width:100%;margin-top:4mm"><tr><td style="width:50%;vertical-align:bottom">{% if doc.unterschrift_kunde %}<img src="{{ doc.unterschrift_kunde }}" style="max-height:22mm"><br>{% elif doc.unterschrift_art in ("Name bestätigt", "Verweigert", "Kunde abwesend") %}<div style="height:22mm;display:flex;align-items:flex-end;font-size:9pt">{% if doc.unterschrift_art == "Name bestätigt" %}Elektronisch bestätigt durch Namenseingabe{% elif doc.unterschrift_art == "Verweigert" %}Unterschrift verweigert{% else %}Kunde bei Abschluss nicht anwesend{% endif %}</div>{% else %}<div style="height:22mm"></div>{% endif %}<div style="border-top:1px solid #30373e;padding-top:1mm;font-size:8pt">Kunde: {{ doc.unterschrift_name or doc.kunde_name or "" }}{% if doc.unterschrift_am %}, {{ ph_datum(doc.unterschrift_am) }}{% endif %}</div></td><td style="width:50%;vertical-align:bottom;padding-left:10mm"><div style="height:22mm"></div><div style="border-top:1px solid #30373e;padding-top:1mm;font-size:8pt">Techniker: {{ techniker }}</div></td></tr></table>
{% if sf and sf.gewaehrleistung_bis %}<p style="font-size:8pt;color:#6b7280;margin-top:6mm">Hinweis: Die gesetzliche Gewährleistung für dieses Produkt läuft bis {{ ph_datum(sf.gewaehrleistung_bis) }}. Diese Serviceleistung lässt Ihre gesetzlichen Rechte unberührt.</p>{% endif %}
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% set lief = frappe.db.get_value("PH Lieferant", doc.lieferant, ["firmenname","strasse","plz","ort","land","kundennummer_bei_lieferant"], as_dict=True) if doc.lieferant and frappe.db.exists("DocType", "PH Lieferant") else None %}
{% set regress = frappe.get_all("PH Lieferantenregress", filters={"servicefall": doc.name}, fields=["name","betrag_gefordert_cent","status","frist_bis"], order_by="modified desc", limit=1) %}
{% set hnr = frappe.db.get_value("PH Produkt", doc.produkt, "hersteller_artikelnr") if doc.produkt and frappe.db.exists("DocType", "PH Produkt") else None %}
{% block titel %}Reklamationsmeldung {{ doc.name }}{% endblock %}
{% block kopfrechts %}Reklamation {{ doc.name }}<br>{{ ph_datum(frappe.utils.nowdate()) }}{% if lief and lief.kundennummer_bei_lieferant %}<br>Kundennr. {{ lief.kundennummer_bei_lieferant }}{% endif %}{% endblock %}
{% block inhalt %}
{% if lief %}<div style="margin-bottom:8mm"><div class="ph-absender">{{ firma.firmenname }} · {{ firma.strasse }} · {{ firma.plz }} {{ firma.ort }}</div><b>{{ lief.firmenname }}</b><br>{{ lief.strasse or "" }}<br>{{ lief.plz or "" }} {{ lief.ort or "" }}<br>{{ lief.land or "" }}</div>{% endif %}
<h1>Reklamationsmeldung{% if doc.art == "Transportschaden" %} – Transportschaden{% endif %}</h1>
<p>Sehr geehrte Damen und Herren,<br>wir melden folgenden Mangel an einem von Ihnen gelieferten Produkt und bitten um Stellungnahme{% if doc.lieferantenrelevant or doc.art == "Transportschaden" %} sowie um Regulierung im Rahmen von Gewährleistung/Garantie bzw. Regress (§ 933b ABGB){% endif %}.</p>
<table class="ph-tabelle"><tbody>
<tr><td style="width:40mm"><b>Produkt</b></td><td>{{ doc.produkt_name or doc.produkt or "–" }}{% if doc.marke %} · {{ doc.marke }}{% endif %}</td></tr>
{% if hnr %}<tr><td><b>Hersteller-Art.-Nr.</b></td><td>{{ hnr }}</td></tr>{% endif %}
{% if doc.ausfuehrung_text or doc.ausfuehrung %}<tr><td><b>Ausführung</b></td><td>{{ doc.ausfuehrung_text or doc.ausfuehrung }}</td></tr>{% endif %}
{% if doc.seriennummer %}<tr><td><b>Seriennummer</b></td><td>{{ doc.seriennummer }}</td></tr>{% endif %}
<tr><td><b>Menge</b></td><td>{{ doc.menge or 1 }}</td></tr>
<tr><td><b>Kauf / Übergabe</b></td><td>{{ ph_datum(doc.kaufdatum) or "–" }} / {{ ph_datum(doc.uebergabe_datum) or "–" }}</td></tr>
{% if doc.lieferung_an_haendler %}<tr><td><b>Ihre Lieferung an uns</b></td><td>{{ ph_datum(doc.lieferung_an_haendler) }}</td></tr>{% endif %}
{% if doc.wareneingang %}<tr><td><b>Wareneingang</b></td><td>{{ doc.wareneingang }}</td></tr>{% endif %}
<tr><td><b>Fehlercode</b></td><td>{{ doc.fehlercode or "–" }} {{ doc.fehlercode_bezeichnung or "" }}{% if doc.ort_am_stueck %} – {{ doc.ort_am_stueck }}{% endif %}</td></tr>
<tr><td><b>Gemeldet am</b></td><td>{{ ph_datum(doc.gemeldet_am) }} ({{ _(doc.kanal) }})</td></tr>
</tbody></table>
<h2>Beschreibung</h2><div>{{ doc.beschreibung }}</div>
{% if doc.pruefergebnis %}<h2>Prüfergebnis</h2><p>{{ doc.pruefergebnis }}</p>{% endif %}
{% set bilder = doc.fotos | selectattr("an_lieferant") | selectattr("bild") | list %}{% if bilder %}<h2>Fotos</h2><table style="width:100%"><tr>{% for z in bilder[:6] %}<td style="width:33%;padding:2mm;text-align:center;vertical-align:top"><img src="{{ frappe.utils.get_url(z.bild) }}" style="max-width:100%;max-height:50mm"><div style="font-size:8pt;color:#6b7280">{{ z.hinweis or "" }}</div></td>{% if loop.index % 3 == 0 and not loop.last %}</tr><tr>{% endif %}{% endfor %}</tr></table>{% if bilder|length > 6 %}<p style="font-size:8pt">Weitere {{ bilder|length - 6 }} Fotos liegen der E-Mail bei.</p>{% endif %}{% endif %}
{% set teile = doc.ersatzteile | selectattr("status", "in", ["Benoetigt","Bestellt"]) | list %}{% if teile %}<h2>Benötigte Ersatzteile</h2><table class="ph-tabelle"><thead><tr><th>Bezeichnung</th><th>Hersteller-Nr.</th><th class="zahl">Menge</th></tr></thead><tbody>{% for z in teile %}<tr><td>{{ z.bezeichnung or z.ersatzteil }}</td><td>{{ z.hersteller_nr or "" }}</td><td class="zahl">{{ z.menge }}</td></tr>{% endfor %}</tbody></table>{% endif %}
<h2>Unser Begehren</h2>
<p>{% if doc.entscheidung in ("Verbesserung","Austausch") %}{{ _(doc.entscheidung) }} des Produkts bzw. kostenlose Lieferung der Ersatzteile.{% elif doc.entscheidung == "Preisminderung" %}Gutschrift (Preisminderung).{% else %}Stellungnahme, Ersatzteil/Austausch oder Gutschrift.{% endif %}{% if regress %} Regressforderung: <b>{{ ph_betrag(regress[0].betrag_gefordert_cent) }}</b> (Vorgang {{ regress[0].name }}).{% endif %}</p>
<p class="ph-hinweis">Bitte antworten Sie innerhalb von 10 Werktagen unter Angabe unserer Nummer <b>{{ doc.name }}</b>. {% if doc.kundentyp == "Verbraucher" %}Der Endkunde ist Verbraucher; die Gewährleistungsfrist (VGG) läuft bis {{ ph_datum(doc.gewaehrleistung_bis) or "–" }}.{% endif %}</p>
<p>Mit freundlichen Grüßen<br>{{ firma.kurzname or firma.firmenname }} · Service</p>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% set einsaetze = frappe.get_all("PH Serviceeinsatz", filters={"servicefall": doc.name, "status": "Erledigt"}, fields=["name","datum","art","ergebnis","techniker"], order_by="datum asc") %}
{% block titel %}Abnahmebestätigung {{ doc.name }}{% endblock %}
{% block kopfrechts %}Servicefall {{ doc.name }}<br>{{ ph_datum(doc.erledigt_am or frappe.utils.nowdate()) }}{% endblock %}
{% block inhalt %}
<div style="margin-bottom:8mm"><div class="ph-absender">{{ firma.firmenname }} · {{ firma.strasse }} · {{ firma.plz }} {{ firma.ort }}</div><b>{{ doc.kunde_name }}</b><br>{{ doc.einsatz_strasse or "" }}<br>{{ doc.einsatz_plz or "" }} {{ doc.einsatz_ort or "" }}</div>
<h1>Abnahmebestätigung</h1>
<p>{% if doc.sprache == "en" %}Dear customer, we confirm the completion of your service case.{% else %}Sehr geehrte Kundin, sehr geehrter Kunde,<br>wir bestätigen den Abschluss Ihres Servicefalls.{% endif %}</p>
<table class="ph-tabelle"><tbody>
<tr><td style="width:40mm"><b>Servicefall</b></td><td>{{ doc.name }} · {{ _(doc.art) }} · gemeldet {{ ph_datum(doc.gemeldet_am) }}</td></tr>
<tr><td><b>Produkt</b></td><td>{{ doc.produkt_name or doc.produkt or "–" }}{% if doc.marke %} ({{ doc.marke }}){% endif %}{% if doc.seriennummer %}, SN {{ doc.seriennummer }}{% endif %}</td></tr>
<tr><td><b>Beanstandung</b></td><td>{{ doc.fehlercode_bezeichnung or "" }}{% if doc.ort_am_stueck %} – {{ doc.ort_am_stueck }}{% endif %}</td></tr>
<tr><td><b>Maßnahme</b></td><td>{{ _(doc.entscheidung) if doc.entscheidung else "–" }}{% if doc.entscheidung == "Preisminderung" and doc.preisminderung_cent %} · Preisminderung {{ ph_betrag(doc.preisminderung_cent) }}{% endif %}{% if doc.entscheidung == "Kulanz" and doc.kulanz_cent %} · Kulanz {{ ph_betrag(doc.kulanz_cent) }}{% endif %}</td></tr>
{% if doc.kosten_kunde_cent %}<tr><td><b>Ihr Kostenanteil</b></td><td>{{ ph_betrag(doc.kosten_kunde_cent) }} (Rechnung folgt gesondert)</td></tr>{% endif %}
</tbody></table>
{% if einsaetze %}<h2>Einsätze</h2><table class="ph-tabelle"><thead><tr><th>Datum</th><th>Art</th><th>Ergebnis</th></tr></thead><tbody>{% for e in einsaetze %}<tr><td>{{ ph_datum(e.datum) }}</td><td>{{ _(e.art) }}</td><td>{{ _(e.ergebnis) if e.ergebnis else "" }}</td></tr>{% endfor %}</tbody></table>{% endif %}
<h2>Abschlussbericht</h2><div>{{ doc.abschlussbericht or "–" }}</div>
{% if doc.status == "Abgelehnt" %}<h2>Begründung</h2><p>{{ doc.entscheidung_begruendung }}</p><p class="ph-hinweis">Diese Entscheidung lässt Ihre gesetzlichen Rechte unberührt. Bei Fragen stehen wir gern zur Verfügung.</p>{% endif %}
<h2>Abnahme</h2>
<p style="font-size:9pt">Hiermit bestätige ich, dass die oben genannte Leistung erbracht wurde{% if doc.entscheidung in ("Verbesserung","Austausch") %} und der beanstandete Mangel behoben ist{% endif %}. Die gesetzliche Gewährleistung{% if doc.gewaehrleistung_bis %} (bis {{ ph_datum(doc.gewaehrleistung_bis) }}){% endif %} bleibt davon unberührt.</p>
<table style="width:100%;margin-top:6mm"><tr><td style="width:50%;vertical-align:bottom">{% if doc.abnahme_unterschrift %}<img src="{{ doc.abnahme_unterschrift }}" style="max-height:22mm"><br>{% else %}<div style="height:22mm"></div>{% endif %}<div style="border-top:1px solid #30373e;padding-top:1mm;font-size:8pt">{{ doc.abnahme_name or doc.kunde_name }}{% if doc.abnahme_am %}, {{ ph_datum(doc.abnahme_am) }}{% else %}, Datum / Unterschrift{% endif %}</div></td><td style="width:50%;vertical-align:bottom;padding-left:10mm"><div style="height:22mm"></div><div style="border-top:1px solid #30373e;padding-top:1mm;font-size:8pt">{{ firma.kurzname or firma.firmenname }} · Service</div></td></tr></table>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% block titel %}Pflege-/Wartungsprotokoll {{ doc.name }}{% endblock %}
{% block kopfrechts %}Vertrag {{ doc.name }}<br>{{ ph_datum(frappe.utils.nowdate()) }}{% endblock %}
{% block inhalt %}
<h1>{{ "Wartungsprotokoll" if doc.art == "Wartungsvertrag" else "Pflegeprotokoll" }}</h1>
<div class="ph-feld"><b>Kunde</b> {{ doc.kunde_name }}</div><div class="ph-feld"><b>Ort</b> {{ doc.strasse or "" }}, {{ doc.plz or "" }} {{ doc.ort or "" }}</div><div class="ph-feld"><b>Vertrag</b> {{ _(doc.art) }} · {{ doc.bereich }} · Intervall {{ doc.intervall_monate }} Monate · Status {{ _(doc.status) }}</div><div class="ph-feld"><b>Nächster Termin</b> {{ ph_datum(doc.naechster_termin) or "–" }}</div>
{% if doc.stuecke %}<h2>Stücke / Anlage</h2><table class="ph-tabelle"><thead><tr><th>Stück</th><th>Marke</th><th>Material / Typ</th><th>Hinweis</th></tr></thead><tbody>{% for s in doc.stuecke %}<tr><td>{{ s.bezeichnung }}</td><td>{{ s.marke or "" }}</td><td>{{ s.material or "" }}</td><td>{{ s.hinweis or "" }}</td></tr>{% endfor %}</tbody></table>{% endif %}
{% if doc.leistungen %}<h2>Leistungsumfang</h2><p>{{ doc.leistungen }}</p>{% endif %}
<h2>Durchgeführte Termine</h2>
{% if doc.protokolle %}<table class="ph-tabelle"><thead><tr><th>Datum</th><th>Durch</th><th>Leistungen</th><th>Messwerte / Befund</th></tr></thead><tbody>{% for p in doc.protokolle | sort(attribute="datum", reverse=True) %}<tr><td>{{ ph_datum(p.datum) }}</td><td>{{ p.durchgefuehrt_von or "" }}</td><td>{{ p.leistungen or "" }}</td><td>{{ p.messwerte or "" }}</td></tr>{% endfor %}</tbody></table>{% else %}<p>Noch keine Termine protokolliert.</p>{% endif %}
<p class="ph-hinweis">Pflege- und Wartungsleistungen ersetzen nicht die gesetzliche Gewährleistung und lassen Herstellergarantien unberührt. Empfehlungen zu Pflegemitteln erhalten Sie nur mit Ihrer Einwilligung.</p>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% set lief = frappe.db.get_value("PH Lieferant", doc.lieferant, ["firmenname","strasse","plz","ort","land","kundennummer_bei_lieferant"], as_dict=True) if frappe.db.exists("DocType", "PH Lieferant") else None %}
{% block titel %}Ersatzteilbestellung {{ doc.name }}{% endblock %}
{% block kopfrechts %}Bestellung {{ doc.name }}<br>{{ ph_datum(doc.datum) }}{% if lief and lief.kundennummer_bei_lieferant %}<br>Kundennr. {{ lief.kundennummer_bei_lieferant }}{% endif %}{% endblock %}
{% block inhalt %}
{% if lief %}<div style="margin-bottom:8mm"><div class="ph-absender">{{ firma.firmenname }} · {{ firma.strasse }} · {{ firma.plz }} {{ firma.ort }}</div><b>{{ lief.firmenname }}</b><br>{{ lief.strasse or "" }}<br>{{ lief.plz or "" }} {{ lief.ort or "" }}<br>{{ lief.land or "" }}</div>{% endif %}
<h1>Ersatzteilbestellung</h1>
{% if doc.kommission %}<div class="ph-feld"><b>Kommission</b> {{ doc.kommission }}</div>{% endif %}{% if doc.servicefall %}<div class="ph-feld"><b>Unsere Reklamation</b> {{ doc.servicefall }}</div>{% endif %}<div class="ph-feld"><b>Kostenträger</b> {{ _(doc.kostentraeger) }}{% if doc.kostentraeger in ("Gewaehrleistung","Garantie") %} – bitte kostenfrei liefern{% endif %}</div><div class="ph-feld"><b>Lieferadresse</b> {{ doc.lieferadresse }}</div>
<table class="ph-tabelle"><thead><tr><th>Pos.</th><th>Hersteller-Nr.</th><th>Bezeichnung</th><th class="zahl">Menge</th><th>Wunschtermin</th></tr></thead><tbody>{% for p in doc.positionen %}<tr><td>{{ loop.index }}</td><td>{{ p.hersteller_nr or "" }}</td><td>{{ p.bezeichnung }}</td><td class="zahl">{{ p.menge }}</td><td>{{ ph_datum(p.wunschtermin) or "" }}</td></tr>{% endfor %}</tbody></table>
{% if doc.notizen %}<p>{{ doc.notizen }}</p>{% endif %}
<p>Bitte bestätigen Sie Liefertermin und Referenz unter Angabe unserer Bestellnummer {{ doc.name }}.</p>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% block titel %}Übernahmeliste {{ doc.name }}{% endblock %}
{% block kopfrechts %}Serviceauftrag {{ doc.name }}<br>{{ ph_datum(doc.abholung_am or frappe.utils.nowdate()) }}{% endblock %}
{% block inhalt %}
<h1>Übernahmeliste – {{ _(doc.art) }}</h1>
<div class="ph-feld"><b>Kunde</b> {{ doc.kunde_name }}</div><div class="ph-feld"><b>Adresse</b> {{ doc.strasse or "" }}, {{ doc.plz or "" }} {{ doc.ort or "" }}</div><div class="ph-feld"><b>Abholung</b> {{ ph_datum(doc.abholung_am) or "–" }}</div><div class="ph-feld"><b>Rückgabe geplant</b> {{ ph_datum(doc.rueckgabe_am) or "–" }}</div>{% if doc.lagerort %}<div class="ph-feld"><b>Lagerort</b> {{ doc.lagerort }}</div>{% endif %}
<table class="ph-tabelle"><thead><tr><th>Pos.</th><th>Stück</th><th>Marke</th><th class="zahl">Menge</th><th>Zustand Übernahme</th><th>Zustand Rückgabe</th><th>Hinweis</th></tr></thead><tbody>{% for p in doc.positionen %}<tr><td>{{ loop.index }}</td><td>{{ p.bezeichnung }}</td><td>{{ p.marke or "" }}</td><td class="zahl">{{ p.menge }}</td><td>{{ p.zustand_uebernahme or "" }}</td><td>{{ p.zustand_rueckgabe or "" }}</td><td>{{ p.hinweis or "" }}</td></tr>{% endfor %}</tbody></table>
{% if doc.leistungen %}<h2>Leistungen</h2><p>{{ doc.leistungen }}</p>{% endif %}
<p class="ph-hinweis">Preis: {% if doc.preis_cent %}{{ ph_betrag(doc.preis_cent) }} inkl. USt{% else %}laut Angebot / auf Anfrage{% endif %}. Die Stücke werden im beschriebenen Zustand übernommen; Fotos liegen im System vor.</p>
<table style="width:100%;margin-top:8mm"><tr><td style="width:50%;vertical-align:bottom">{% if doc.uebernahme_unterschrift %}<img src="{{ doc.uebernahme_unterschrift }}" style="max-height:22mm"><br>{% else %}<div style="height:22mm"></div>{% endif %}<div style="border-top:1px solid #30373e;padding-top:1mm;font-size:8pt">Übernahme Kunde{% if doc.uebernahme_am %}, {{ ph_datum(doc.uebernahme_am) }}{% endif %}</div></td><td style="width:50%;vertical-align:bottom;padding-left:10mm">{% if doc.rueckgabe_unterschrift %}<img src="{{ doc.rueckgabe_unterschrift }}" style="max-height:22mm"><br>{% else %}<div style="height:22mm"></div>{% endif %}<div style="border-top:1px solid #30373e;padding-top:1mm;font-size:8pt">Rückgabe Kunde{% if doc.rueckgabe_am_unterschrift %}, {{ ph_datum(doc.rueckgabe_am_unterschrift) }}{% endif %}</div></td></tr></table>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% set sf = frappe.get_doc("PH Servicefall", doc.servicefall) if doc.servicefall else None %}
{% block titel %}Belastungsanzeige {{ doc.name }}{% endblock %}
{% block kopfrechts %}Belastungsanzeige {{ doc.name }}<br>{{ ph_datum(doc.belastung_gesendet_am or frappe.utils.nowdate()) }}{% if doc.herstellerauftrag %}<br>Ihr Auftrag {{ doc.herstellerauftrag }}{% endif %}{% if doc.lieferant_referenz %}<br>Ihre Referenz {{ doc.lieferant_referenz }}{% endif %}{% endblock %}
{% block inhalt %}
<div class="ph-feld" style="margin-bottom:6mm"><b>An</b> {{ doc.lieferant or "" }}{% if doc.marke %} ({{ doc.marke }}){% endif %}</div>
<h1>Belastungsanzeige</h1>
<p>Zur nachstehenden Reklamation belasten wir Sie mit den uns entstandenen Kosten (Rückgriff § 933b ABGB).</p>
{% if sf %}<table style="width:100%;margin-bottom:5mm"><tr>
<td style="width:50%;vertical-align:top"><div class="ph-feld"><b>Reklamation</b> {{ sf.name }}</div><div class="ph-feld"><b>Produkt</b> {{ sf.produkt_name or sf.produkt or "–" }}{% if sf.ausfuehrung_text %}, {{ sf.ausfuehrung_text }}{% endif %}</div>{% if sf.seriennummer or sf.e_nummer %}<div class="ph-feld"><b>Gerät</b> {% if sf.e_nummer %}E-Nr. {{ sf.e_nummer }} {% endif %}{% if sf.fd_nummer %}FD {{ sf.fd_nummer }} {% endif %}{% if sf.seriennummer %}S/N {{ sf.seriennummer }}{% endif %}</div>{% endif %}</td>
<td style="width:50%;vertical-align:top"><div class="ph-feld"><b>Fehler</b> {{ sf.fehlercode or "" }} {{ sf.fehlercode_bezeichnung or "" }}</div><div class="ph-feld"><b>Übergabe an Kunden</b> {{ ph_datum(sf.uebergabe_datum) if sf.uebergabe_datum else "–" }}</div><div class="ph-feld"><b>Behoben am</b> {{ ph_datum(sf.erledigt_am) if sf.erledigt_am else "–" }}</div></td></tr></table>
{% if sf.fotos %}<p class="ph-hinweis">Fotodokumentation: {{ sf.fotos | selectattr("an_lieferant") | list | length }} Datei(en) liegen der E-Mail bei bzw. sind auf Anfrage abrufbar.</p>{% endif %}{% endif %}
<table class="ph-tabelle"><thead><tr><th>Kostenart</th><th>Beschreibung</th><th class="zahl">Menge</th><th class="zahl">Satz</th><th class="zahl">Betrag</th></tr></thead><tbody>
{% for z in doc.kosten %}<tr><td>{{ _(z.kostenart) }}</td><td>{{ z.beschreibung or "" }}</td><td class="zahl">{{ frappe.utils.fmt_money(z.menge, 2) }} {{ z.einheit if z.einheit != "pauschal" else "" }}</td><td class="zahl">{{ ph_betrag(z.satz_cent) }}</td><td class="zahl">{{ ph_betrag(z.betrag_cent) }}</td></tr>{% else %}<tr><td colspan="5">{{ doc.beschreibung or "Kosten laut Reklamation" }}</td></tr>{% endfor %}
</tbody><tfoot><tr><td colspan="4" style="text-align:right"><b>Summe</b></td><td class="zahl"><b>{{ ph_betrag(doc.betrag_gefordert_cent) }}</b></td></tr></tfoot></table>
<p style="margin-top:5mm">Bitte schreiben Sie den Betrag {% if doc.zahlungsfrist_bis %}bis <b>{{ ph_datum(doc.zahlungsfrist_bis) }}</b>{% else %}innerhalb von {{ doc.zahlungsfrist_tage or 30 }} Tagen{% endif %} gut (Gutschrift unter Angabe von {{ doc.name }}) oder verrechnen Sie ihn mit Ihrer nächsten Rechnung.</p>
{% if doc.ruecksendung_noetig %}<p>Die reklamierte Ware liegt zur Abholung bereit{% if doc.abholung_frist %} – bitte bis {{ ph_datum(doc.abholung_frist) }} abholen{% endif %}.</p>{% endif %}
<p style="font-size:8pt;color:#6b7280;margin-top:6mm">Beträge ohne Umsatzsteuer, sofern nicht anders angegeben. Die umsatzsteuerliche Behandlung (Schadenersatz/Entgelt) stimmen wir auf Wunsch ab.</p>
{% endblock %}
